body_md:
\label{T:3.1}
If a special spacelike Frenet curve $C$ in $E_1^4$ is a
generalized spacelike Mannheim curve, then the first curvature
function ${k_1}$ and the second curvature function
 ${k_2}$ of $C$ satisfy the equality
\begin{equation}\label{3.2}
\begin{array}{l}
{k_1}\left( s \right) =  - \alpha \left( {{\mu _1}k_1^2\left( s
\right) + {\mu _2}k_2^2\left( s \right)} \right)\,\,,\,\,s \in L
 \end{array}
\end{equation}
where $\alpha $ is a constant number and ${\mu _1} = {\mu _2} =  -
1$ when ${{\bf{e}}_4}$ is timelike or ${\mu _1} =  - 1\,,\,\,{\mu
_2} = 1$ when ${{\bf{e}}_3}$ is timelike or ${\mu _1} = {\mu _2} =
1$ when ${{\bf{e}}_2}$ is timelike.

Let $C$ be a generalized spacelike
Mannheim curve and ${C^*}$ be the generalized spacelike Mannheim
mate curve of $C$ with the diagram;
$$
\begin{array}{l}
 \,\,\,\,\,\,\,\,\,\,\,\,\mathop {\bf{c}}\limits_{ \cdot \,\, \cdot } \,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,{\mathop {\bf{c}}\limits_{ \cdot \,\, \cdot } ^*}\, \\
 f:\,\,\,\,L\,\,\,\,\,\, \to \,\,\,\,\,{L^*}\, \\
 \,\,\,\,\,\,\,\,\,\,\,\,\,\, \downarrow \,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\, \downarrow  \\
 \phi \,:\,\,\,E_1^4\,\,\, \to \,\,\,E_1^4. \\
 \end{array}
$$
A smooth function $f$ is defined by $f\left( s \right) = \int
{\left\| {\frac{{d{{\bf{c}}^*}\left( s \right)}}{{ds}}} \right\|}
ds = {s^*}$ and ${s^*}$ is the arc-length parameter of ${C^*}$.
Also $\phi $ is a bijection which is defined by $\phi \left(
{{\bf{c}}\left( s \right)} \right) = {{\bf{c}}^*}\left( {f\left( s
\right)} \right).$ Thus, the spacelike curve ${C^*}$ is
reparametrized by
\begin{equation}\label{3.3}
\begin{array}{l}
{{\bf{c}}^*}\left( {f\left( s \right)} \right) = {\bf{c}}\left( s
\right) + \alpha \left( s \right){{\bf{e}}_2}\left( s \right)
 \end{array}
\end{equation}
where $\alpha $ is a smooth function. By differentiating both
sides of (3.3) with respect to $s$
\begin{equation}\label{3.4}
\begin{array}{l}
 f'\left( s \right){\bf{e}}_1^*\left( {f\left( s \right)} \right) = \left( {1 + {\mu _1}\alpha \left( s \right){k_1}\left( s \right)} \right){{\bf{e}}_1} + \alpha '\left( s \right){{\bf{e}}_2}\left( s \right) \\
 \,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\, + \alpha \left( s \right){k_2}\left( s \right){{\bf{e}}_3}\left( s \right) \\
 \end{array}
\end{equation}
is obtained.

\noindent On the other hand, since the first normal line at the
each point of $C$ is lying in the plane generated by the second
normal line and the third normal line of ${C^*}$ at the
corresponding points under bijection $\phi $, the vector field
${{\bf{e}}_2}\left( s \right)$ is given by

$$
\begin{array}{l}
{{\bf{e}}_2}\left( s \right) = g\left( s \right){\bf{e}}_3^*\left(
{f\left( s \right)} \right) + h\left( s \right){\bf{e}}_4^*\left(
{f\left( s \right)} \right)
 \end{array}
$$
where $g$ and $h$ are some smooth functions on $L$. If we take
into consideration
$$
\begin{array}{l}
\left\langle {{\bf{e}}_1^*\left( {f\left( s \right)}
\right),\,g\left( s \right){\bf{e}}_3^*\left( {f\left( s \right)}
\right) + h\left( s \right){\bf{e}}_4^*\left( {f\left( s \right)}
\right)} \right\rangle  = 0
 \end{array}
$$
and the equation (3.4), then we have $\alpha '\left( s \right)
=0$. So we rewrite the equation (3.4) as

\begin{equation}\label{3.5}
\begin{array}{l}
f'\left( s \right){\bf{e}}_1^*\left( {f\left( s \right)} \right) =
\left( {1 + {\mu _1}\alpha {k_1}\left( s \right)}
\right){{\bf{e}}_1}\left( s \right) + \alpha {k_2}\left( s
\right){{\bf{e}}_3}\left( s \right),
 \end{array}
\end{equation}
that is,
$$
\begin{array}{l}
{\bf{e}}_1^*\left( {f\left( s \right)} \right) = \frac{{\left( {1
+ {\mu _1}\alpha {k_1}\left( s \right)} \right)}}{{f'\left( s
\right)}}{{\bf{e}}_1}\left( s \right) + \frac{{\alpha {k_2}\left(
s \right)}}{{f'\left( s \right)}}{{\bf{e}}_3}\left( s \right)
 \end{array}
$$
where
$$
\begin{array}{l}
f'\left( s \right) = \sqrt {\left| {{{\left( {1 + {\mu _1}\alpha
{k_1}\left( s \right)} \right)}^2} + \varepsilon_3 {{\left(
{\alpha {k_2}\left( s \right)} \right)}^2}} \right|}
\,,\,\,\varepsilon_3  = \left\{ \begin{array}{l}
  - 1\,\,,\,\,{{\bf{e}}_3}\,\,{\rm{is\,\,  timelike}}{\rm{,}} \\
 \,\,\,\,1\,\,\,,\,\,{{\bf{e}}_3}\,\,{\rm{is\,\,  spacelike}}{\rm{.}} \\
 \end{array} \right.
 \end{array}
$$
By taking differentiation both sides of the equations (3.5) with
respect to $s$,
\begin{equation}\label{3.6}
\begin{array}{l}
 f'\left( s \right)k_1^*\left( {f\left( s \right)} \right){\bf{e}}_2^*\left( {f\left( s \right)} \right) = {\left( {\frac{{1 + {\mu _1}\alpha {k_1}\left( s \right)}}{{f'\left( s \right)}}} \right)^\prime }{{\bf{e}}_1}\left( s \right) \\
 \,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\, + \left( {\frac{{\left( {1 + {\mu _1}\alpha {k_1}\left( s \right)} \right){k_1}\left( s \right) + {\mu _2}\alpha {{\left( {{k_2}\left( s \right)} \right)}^2}}}{{f'\left( s \right)}}} \right){{\bf{e}}_2}\left( s \right) \\
 \,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\, + {\left( {\frac{{\alpha {k_2}\left( s \right)}}{{f'\left( s \right)}}} \right)^\prime }{{\bf{e}}_3}\left( s \right) + \left( {\frac{{\alpha {k_2}\left( s \right){k_3}\left( s \right)}}{{f'\left( s \right)}}} \right){{\bf{e}}_4}\left( s \right) \\
 \end{array}
\end{equation}
is obtained for $s \in L$. Since
$$
\begin{array}{l}
\left\langle {{\bf{e}}_2^*\left( {f\left( s \right)}
\right),\,g\left( s \right){\bf{e}}_3^*\left( {f\left( s \right)}
\right) + h\left( s \right){\bf{e}}_4^*\left( {f\left( s \right)}
\right)} \right\rangle  = 0,
 \end{array}
$$
then in the equation (3.6) the coefficient of ${{\bf{e}}_2}\left(
s \right)$ vanishes, that is,
$$\begin{array}{l}
\left( {1 + {\mu _1}\alpha {k_1}\left( s \right)}
\right){k_1}\left( s \right) + {\mu _2}\alpha {\left( {{k_2}\left(
s \right)} \right)^2} = 0.
 \end{array}
$$
Thus, ${k_1}\left( s \right) =  - \alpha \left( {{\mu
_1}k_1^2\left( s \right) + {\mu _2}k_2^2\left( s \right)} \right)$
is satisfied. This completes the proof.

\noindent If we investigate the special cases separately, then we
have

in the Case 1;
$$
\begin{array}{l}
{k_1}\left( s \right) = \alpha \left( {k_1^2\left( s \right) +
k_2^2\left( s \right)} \right),
 \end{array}
$$

in the Case 2;
$$
\begin{array}{l}
{k_1}\left( s \right) = \alpha \left( {k_1^2\left( s \right) -
k_2^2\left( s \right)} \right),
 \end{array}
$$

in the Case 3;
$$
\begin{array}{l}
{k_1}\left( s \right) =  - \alpha \left( {k_1^2\left( s \right) +
k_2^2\left( s \right)} \right).
 \end{array}
$$


\begin{theorem}\label{T:3.2}
Let $C$ be a special spacelike Frenet curve in $E_1^4$ whose
curvature functions ${k_1}$ and ${k_2}$ are non-constant functions
and satisfy the equality ${k_1}\left( s \right) =  - \alpha \left(
{{\mu _1}k_1^2\left( s \right) + {\mu _2}k_2^2\left( s \right)}
\right)$, where $\alpha$ is non-zero constant, for all $s \in L$.
If the spacelike curve ${C^*}$ given by
$$
\begin{array}{l}
{{\bf{c}}^*}\left( s \right) = {\bf{c}}\left( s \right) + \alpha
{{\bf{e}}_2}\left( s \right)
 \end{array}
$$
is a special spacelike Frenet curve, then ${C^*}$ is a generalized
spacelike Mannheim mate curve of $C$.
\end{theorem}

Let $C$ be a spacelike Frenet curve in $E_1^4$
with the Frenet frame field $\left\{
{{{\bf{e}}_1},\,{{\bf{e}}_2},\,{{\bf{e}}_3},\,{{\bf{e}}_4}}
\right\}$ and curvature functions ${k_1},\,{k_2}$ and ${k_3}$.
Also, we assume that ${C^*}$ be a spacelike special Frenet curve
in $E_1^4$ with the Frenet frame field $\left\{
{{\bf{e}}_1^*,\,{\bf{e}}_2^*,\,{\bf{e}}_3^*,\,{\bf{e}}_4^*}
\right\}$ and curvature functions $k_1^*,\,k_2^*\,$ and $k_3^*$.

\noindent Let the first normal line of $C$ be linearly dependent
with the third normal line of ${C^*}$ at the corresponding points
$C$ and ${C^*}$, respectively. Then the parametrization of ${C^*}$
is
\begin{equation}\label{3.9}
\begin{array}{l}
{{\bf{c}}^*}\left( {f\left( s \right)} \right) = {\bf{c}}\left( s
\right) + \alpha \left( s \right){{\bf{e}}_2}\left( s \right)
 \end{array}
\end{equation}
for all $s \in L$. If ${s^*}$ is the arc-length parameter of
${C^*}$, then
\begin{equation}\label{3.10}
\begin{array}{l}
{s^*} = \int\limits_0^s {\sqrt {\left| {{{\left( {1 + {\mu
_1}\alpha {k_1}} \right)}^2} + \varepsilon_2 \left( {\alpha
'\left( s \right)} \right) + \varepsilon_3 {{\left( {\alpha \left(
s \right){k_2}\left( s \right)} \right)}^2}} \right|} } ds
 \end{array}
\end{equation}
where
$$
\begin{array}{l}
\varepsilon_i  = \left\{ \begin{array}{l}
  - 1\,\,,\,\,{{\bf{e}}_i}\,\,{\rm{is}}\,\,{\rm{timelike}} \\
 \,\,\,1\,\,\,,\,\,{{\bf{e}}_i}\,\,{\rm{is}}\,\,{\rm{spacelike}} \\
 \end{array} \right.,\,\,\,{\rm{for}}\,\,\,\,\, {\rm{ }}2 \le i \le 4
 \end{array}
$$
and
$$
\begin{array}{l}
f:\,L \to {L^*} \\
 \,\,\,\,\,\,\,s\,\, \to \,f\left( s \right) = {s^*}. \\
 \end{array}
$$
Moreover, $\phi :C \to {C^*}$ is a bijection given by $\phi \left(
{{\bf{c}}\left( s \right)} \right) = {{\bf{c}}^*}\left( {f\left( s
\right)} \right)$.

\noindent By differentiating the equation (3.9) with respect to
$s$ and using Frenet formulas, we have
\begin{equation}\label{3.11}
\begin{array}{l}
 f'\left( s \right){\bf{e}}_1^*\left( {f\left( s \right)} \right) = \left( {1 + {\mu _1}\alpha \left( s \right){k_1}\left( s \right)} \right){{\bf{e}}_1}\left( s \right) + \alpha '\left( s \right){{\bf{e}}_2}\left( s \right) \\
 \,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\, + \alpha \left( s \right){k_2}\left( s \right){{\bf{e}}_3}\left( s \right). \\
 \end{array}
\end{equation}
Since ${\bf{e}}_4^*\left( {f\left( s \right)} \right) =  \mp
{{\bf{e}}_2}\left( s \right)$, then
$$
\begin{array}{l}
 \left\langle {f'\left( s \right){\bf{e}}_1^*\left( {f\left( s \right)} \right),\,{\bf{e}}_4^*\left( {f\left( s \right)} \right)} \right\rangle  = \left\langle {\left( {1 + {\mu _1}\alpha \left( s \right){k_1}\left( s \right)} \right){{\bf{e}}_1}\left( s \right) + \alpha '\left( s \right){{\bf{e}}_2}\left( s \right)} \right. \\
 \,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\left. { + \alpha \left( s \right){k_2}\left( s \right){{\bf{e}}_3}\left( s \right),\, \mp {{\bf{e}}_2}\left( s \right)} \right\rangle , \\
 \end{array}
$$
that is,
$$
\begin{array}{l}
0 =  \mp \alpha '\left( s \right).
 \end{array}
$$
It is easily seen that $\alpha $ is a constant number from the
last equation. Thus, hereafter we can denote $\alpha \left( s
\right) = \alpha $, for all $s \in L.$

\noindent From the equation (3.10), we get
$$
\begin{array}{l}
f'\left( s \right) = \sqrt {\left| {{{\left( {1 + {\mu _1}\alpha
{k_1}\left( s \right)} \right)}^2} + \varepsilon_3 {{\left(
{\alpha {k_2}\left( s \right)} \right)}^2}} \right|}  > 0
 \end{array}
$$
where
$$
\begin{array}{l}
\varepsilon_3 = \left\{ \begin{array}{l}
 - 1\,\,,\,\,{{\bf{e}}_i}\,\,{\rm{is}}\,\,{\rm{timelike}} \\
 \,\,\,\,1\,\,,\,\,{{\bf{e}}_i}\,\,{\rm{is}}\,\,{\rm{spacelike}} \\
 \end{array} \right. \,\,\,\,,\,{\rm{for   }}\,\,\,\,\, 2 \le i \le 4.
 \end{array}
$$
Then, we rewrite the equation (3.11) as follows;
$$
\begin{array}{l}
{\bf{e}}_1^*\left( {f\left( s \right)} \right) = \left( {\frac{{1
+ {\mu _1}\alpha {k_1}\left( s \right)}}{{f'\left( s \right)}}}
\right){{\bf{e}}_1}\left( s \right) + \left( {\frac{{\alpha
{k_2}\left( s \right)}}{{f'\left( s \right)}}}
\right){{\bf{e}}_3}\left( s \right).\
 \end{array}
$$
The differentiation of the last equation with respect to $s$ is
\begin{equation}\label{3.12}
\begin{array}{l}
 f'\left( s \right)k_1^*\left( {f\left( s \right)} \right){\bf{e}}_2^*\left( {f\left( s \right)} \right) = {\left( {\frac{{1 + {\mu _1}\alpha {k_1}\left( s \right)}}{{f'\left( s \right)}}} \right)^\prime }{{\bf{e}}_1}\left( s \right) \\
 \,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\, + \left( {\frac{{{k_1}\left( s \right) + {\mu _1}\alpha k_1^2\left( s \right) + {\mu _2}\alpha k_2^2\left( s \right)}}{{f'\left( s \right)}}} \right){{\bf{e}}_2}\left( s \right) \\
 \,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\, \,\,\,\,\,\,\,\,\,\,\,\,\,+ {\left( {\frac{{\alpha {k_2}\left( s \right)}}{{f'\left( s \right)}}} \right)^\prime }{{\bf{e}}_3}\left( s \right) + \left( {\frac{{\alpha {k_2}\left( s \right){k_3}\left( s \right)}}{{f'\left( s \right)}}} \right){{\bf{e}}_4}\left( s \right). \\
 \end{array}
\end{equation}
Since $\left\langle {f'\left( s \right)k_1^*\left( {f\left( s
\right)} \right){\bf{e}}_2^*\left( {f\left( s \right)}
\right),\,{\bf{e}}_4^*\left( {f\left( s \right)} \right)}
\right\rangle  = 0$ and ${\bf{e}}_4^*\left( {f\left( s \right)}
\right) =  \mp {{\bf{e}}_2}\left( s \right)$ for all $s \in L$, we
obtain
$$
\begin{array}{l}
{k_1}\left( s \right) + {\mu _1}\alpha k_1^2\left( s \right) +
{\mu _2}\alpha k_2^2\left( s \right) = 0
 \end{array}
$$
is satisfied. Then,
\begin{equation}\label{3.13}
\begin{array}{l}
\alpha  =  - \frac{{{k_1}\left( s \right)}}{{{\mu _1} k_1^2\left(
s \right) + {\mu _2} k_2^2\left( s \right)}}
 \end{array}
\end{equation}
is a non-zero constant number. Thus, from the equation (3.12), it
is seen that
$$
\begin{array}{l}
 {\bf{e}}_2^*\left( {f\left( s \right)} \right) = \frac{1}{{f'\left( s \right)K\left( s \right)}}{\left( {\frac{{1 + {\mu _1}\alpha {k_1}\left( s \right)}}{{f'\left( s \right)}}} \right)^\prime }{{\bf{e}}_1}\left( s \right) + \frac{1}{{f'\left( s \right)K\left( s \right)}}\left( {\frac{{\alpha {k_2}\left( s \right)}}{{f'\left( s \right)}}} \right){{\bf{e}}_3}\left( s \right) \\
 \,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\, + \frac{1}{{f'\left( s \right)K\left( s \right)}}\left( {\frac{{\alpha {k_2}\left( s \right){k_3}\left( s \right)}}{{f'\left( s \right)}}} \right){{\bf{e}}_4}\left( s \right) \\
\end{array}
$$
where $K\left( s \right) = k_1^*\left( {f\left( s \right)}
\right)$ for all $s \in L$. By differentiating the last equation
with respect to $s$, we obtain
$$
\begin{array}{l}
 f'\left( s \right)\left[ {{\mu _1}k_1^*\left( {f\left( s \right)} \right){\bf{e}}_1^*\left( {f\left( s \right)} \right) + k_2^*\left( {f\left( s \right)} \right){{\bf{e}}_3^*}\left( {f\left( s \right)} \right)} \right] = {\left( {\frac{1}{{f'\left( s \right)K\left( s \right)}}{{\left( {\frac{{1 + {\mu _1}\alpha {k_1}\left( s \right)}}{{f'\left( s \right)}}} \right)}^\prime }} \right)^\prime }{{\bf{e}}_1}\left( s \right) \\
 \,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\, + \left( {\frac{k_1{\left(s \right)}}{{f'\left( s \right)K\left( s \right)}}{{\left( {\frac{{1 + {\mu _1}\alpha {k_1}\left( s \right)}}{{f'\left( s \right)}}} \right)}^\prime } + \frac{{{\mu _2}{k_2}\left( s \right)}}{{f'\left( s \right)K\left( s \right)}}{{\left( {\frac{{\alpha {k_2}\left( s \right)}}{{f'\left( s \right)}}} \right)}^\prime }} \right){{\bf{e}}_2}\left( s \right) \\
 \,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\, + \left( {{{\left( {\frac{1}{{f'\left( s \right)K\left( s \right)}}{{\left( {\frac{{\alpha {k_2}\left( s \right)}}{{f'\left( s \right)}}} \right)}^\prime }} \right)}^\prime } + \frac{{{\mu _3}{k_3}\left( s \right)}}{{f'\left( s \right)K\left( s \right)}}\left( {\frac{{\alpha {k_2}\left( s \right){k_3}\left( s \right)}}{{f'\left( s \right)}}} \right)} \right){{\bf{e}}_3}\left( s \right) \\
 \,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\, + \left( {{{\left( {\frac{1}{{f'\left( s \right)K\left( s \right)}}{{\left( {\frac{{\alpha {k_2}\left( s \right){k_3}\left( s \right)}}{{f'\left( s \right)}}} \right)}^\prime }} \right)}^\prime } + \frac{{{k_3}\left( s \right)}}{{f'\left( s \right)K\left( s \right)}}{{\left( {\frac{{\alpha {k_2}\left( s \right)}}{{f'\left( s \right)}}} \right)}^\prime }} \right){{\bf{e}}_4}\left( s \right) \\
\end{array}
$$
for all $s \in L$. If we take into consideration
$$
\begin{array}{l}
\left\langle {f'\left( s \right)\left( {{\mu _1}k_1^*\left(
{f\left( s \right)} \right){\bf{e}}_1^*\left( {f\left( s \right)}
\right) + k_2^*\left( {f\left( s \right)}
\right){{\bf{e}}_3^*}\left( {f\left( s \right)} \right)}
\right)\,,\,\,{\bf{e}}_4^*\left( {f\left( s \right)} \right)}
\right\rangle  = 0\
\end{array}
$$
and
$$
\begin{array}{l}
{\bf{e}}_4^*\left( {f\left( s \right)} \right) =  \mp
{{\bf{e}}_2}\left( s \right),\
\end{array}
$$
then
$$
\begin{array}{l}
 {\mu _1}\alpha {k_1}\left( s \right){k_1}^\prime \left( s \right) {f'\left( s \right)}- {k_1}\left( s \right)\left( {1 + {\mu _1}\alpha {k_1}\left( s \right)} \right)f''\left( s \right) \\
 \,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\, + {\mu _2}\alpha {k_2}\left( s \right){k_2}^\prime \left( s \right){f'\left( s \right)} - {\mu _2}\alpha k_2^2\left( s \right)f''\left( s \right) = 0. \\
\end{array}
$$
If we arrange the last equation, then we find
\begin{equation}\label{3.14}
\begin{array}{l}
 \alpha \left( {{\mu _1}{k_1}\left( s \right){{k'}_1}\left( s \right) + {\mu _2}{k_2}\left( s \right){{k'}_2}\left( s \right)} \right)f'\left( s \right) \\
 \,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\,\, - \left( {{k_1} + \alpha \left( {{\mu _1}k_1^2\left( s \right) + {\mu _2}k_2^2\left( s \right)} \right)} \right)f''\left( s \right) = 0. \\
 \end{array}
\end{equation}
Moreover, the differentiation of the equation (3.13) with respect
to $s$ is
$$
\begin{array}{l}
{k'_1}\left( s \right) + 2\alpha \left( {{\mu _1}{k_1}\left( s
\right){{k'}_1}\left( s \right) + {\mu _2}{k_2}\left( s
\right){{k'}_2}\left( s \right)} \right) = 0.
\end{array}
$$
From the above equation, we see
\begin{equation}\label{3.15}
\begin{array}{l}
 - \frac{{{{k'}_1}\left( s \right)}}{2} = \alpha \left( {{\mu
_1}{k_1}\left( s \right){{k'}_1}\left( s \right) + {\mu
_2}{k_2}\left( s \right){{k'}_2}\left( s \right)} \right).
 \end{array}
\end{equation}
If we substitute the equations (3.13) and (3.15) into the equation
(3.14), we obtain
$$
\begin{array}{l}
 - \frac{{{{k'}_1}\left( s \right)}}{2} = 0.
\end{array}
$$
Finally, we find that the first curvature function is constant
(that is, positive constant).

\noindent Thus, from the equation (3.15) it is seen that the
second curvature function ${k_2}$ is positive constant, too. This
completes the proof.

\noindent In \cite{Eis}, a formula of parametric equation of
Mannheim curve is given in ${E^3}$. Moreover, the parametric
equation of generalized Mannheim curve in ${E^4}$ is obtained in
\cite{Mat2}. The following theorem gives a parametric
representation of a generalized spacelike Mannheim curve with
timelike second binormal vector in $E_1^4$.

\begin{theorem}
Let   be a spacelike special curve defined by
$$
\begin{array}{l}
{\bf{c}}\left( u \right) = \left[ {\begin{array}{*{20}{c}}
   {\alpha \int {f\left( u \right)\sinh udu} }  \\
   {\alpha \int {f\left( u \right)\cosh udu} }  \\
   {\alpha \int {f\left( u \right)g\left( u \right)du} }  \\
   {\alpha \int {f\left( u \right)h\left( u \right)du} }  \\
\end{array}} \right]\
\end{array}
$$
for $u \in I \subset\mathbb{R}$. Here $\alpha$ is a non-zero
constant number, $g:I \to \mathbb{R}$ and $h:I \to \mathbb{R}$ are
any smooth functions and the positive valued smooth function $f:I
\to \mathbb{R}$ is given by

